    sse_encode_String(self.fileName, serializer);
    sse_encode_String(self.message, serializer);
    sse_encode_i_64(self.bytesUploaded, serializer);
    sse_encode_i_64(self.bytesTotal, serializer);
    sse_encode_i_32(self.attempt, serializer);
    sse_encode_i_32(self.total, serializer);
    sse_encode_String(self.mediaKey, serializer);
    sse_encode_bool(self.isError, serializer);
    sse_encode_bool(self.skipped, serializer);
    sse_encode_String(self.skipCode, serializer);
    sse_encode_String(self.skipReason, serializer);
  }

  @protected
  void sse_encode_upload_progress(
    UploadProgress self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_64(self.totalBytes, serializer);
    sse_encode_i_64(self.uploadedBytes, serializer);
    sse_encode_i_64(self.elapsedMs, serializer);
    sse_encode_i_64(self.speedBytesPerSec, serializer);
    sse_encode_i_64(self.etaSeconds, serializer);
  }

  @protected
  void sse_encode_upload_result(UploadResult self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.path, serializer);
    sse_encode_String(self.mediaKey, serializer);
    sse_encode_bool(self.isError, serializer);
    sse_encode_bool(self.skipped, serializer);
    sse_encode_String(self.skipCode, serializer);
    sse_encode_String(self.skipReason, serializer);
    sse_encode_String(self.errorMessage, serializer);
  }

  @protected
  void sse_encode_upload_summary(UploadSummary self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.total, serializer);
    sse_encode_i_32(self.succeeded, serializer);
    sse_encode_i_32(self.failed, serializer);
    sse_encode_i_32(self.skipped, serializer);
    sse_encode_list_upload_result(self.results, serializer);
  }
}
